(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.01+t*0.5)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.012-t*0.4)*8;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.2],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.5],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 1.3],
    [80+Math.sin(t*0.7+3)*70, 40+Math.cos(t*0.45+2)*50, 0.14, 2.1, 0.8],
    [400+Math.cos(t*0.6+1)*60, 200+Math.sin(t*0.8)*55, 0.11, 1.8, 1.0]
  ];
  let aS = 0, iS = 0, eField = 0;
  for (const [sX, sY, f, sp, mass] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const grav = mass / (1 + d*0.02);
    aS += Math.sin(d*f - t*sp) * grav;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * grav;
    eField += Math.sin(d*0.15 - t*1.5) / (1 + d*0.01) * mass;
  }
  const n = src.length;
  const act = aS/n, inh = iS/n;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const potential = Math.sin(dist*0.03 - t*0.4) * 0.5 / (1 + dist*0.005);
  const kinetic = Math.sin(dist*0.08 + ang*2 - t*2.5) * 0.3;
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const flow = Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1);
  const micro = Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5;
  const raw = act - inh*0.65 + (flow*0.15 + spiral*0.3 + potential + kinetic*0.5 + eField*0.1);
  const reaction = Math.tanh(raw * 3.5);
  const cell = Math.tanh(micro * 2.0) * 0.25;
  const blend = reaction*0.8 + cell*0.2;
  const v = blend*0.5+0.5;
  const pal = [[2,2,15],[10,0,60],[20,0,120],[0,180,255],[0,255,200],[120,255,0],[255,60,180],[255,0,80],[255,200,0],[2,2,15]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const glow = Math.pow(Math.abs(reaction), 0.6);
  const edge = Math.abs(reaction) > 0.6 ? 1.4 : 1.0;
  const lum = (0.7 + glow*0.6) * edge;
  const hot = Math.max(0, Math.abs(reaction) - 0.85) * 6;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum + hot*120)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum + hot*180)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum + hot*200)|0)
  ];
}
